  1	/**
  2	 * Límites de tasa adaptativos por upstream — porte de OmniRoute
  3	 * (`open-sse/services/rateLimitManager.ts`, a58000c7, MIT).
  4	 *
  5	 * Un limitador por proveedor y credencial (y por modelo donde el cupo es por
  6	 * modelo) que aprende el ritmo de lo que el upstream dice: sus cabeceras de
  7	 * límite, la espera que pide un 429 y el tope que algunos escriben en prosa.
  8	 * Una credencial sin protección activada pasa directa.
  9	 *
 10	 * Divergencias declaradas:
 11	 * - El estado vive en la instancia, no en módulos globales ni en la base de
 12	 *   datos: lo aprendido no persiste entre arranques.
 13	 * - Los ajustes de cola (`RateLimitQueueSettings`) llegan al construir; la
 14	 *   referencia los lee de sus ajustes de resiliencia, con límites por defecto.
 15	 *   Aquí el defecto es sin límite, el mismo valor que la referencia da a un 0.
 16	 * - Las claves por familia de cuota de `codex` y `antigravity` dependen de
 17	 *   módulos que no se portan; esos proveedores usan la clave por credencial.
 18	 * - No se portan las sobreescrituras por conexión, el tope de espera en cola,
 19	 *   la vigilancia de colas atascadas ni la expulsión por inactividad: piezas
 20	 *   de un servicio que vive semanas con miles de conexiones.
 21	 */
 22	import { requestCapSettings, parseRequestCapFromBody } from './requestCap.ts'
 23	import { ANTHROPIC_HEADERS, parseResetTime, STANDARD_HEADERS, toPlainHeaders } from './rateLimitHeaders.ts'
 24	import { RequestLimiter, type RequestLimiterSettings } from './requestLimiter.ts'
 25	import { parseRetryAfterFromBody } from './retryHints.ts'
 26	
 27	/** Los ajustes de cola de toda credencial protegida; 0 o ausente es sin límite. */
 28	export interface RateLimitQueueSettings {
 29	  requestsPerMinute?: number
 30	  minTimeBetweenRequestsMs?: number
 31	  concurrentRequests?: number
 32	}
 33	
 34	export interface LearnedLimit {
 35	  provider: string
 36	  credentialId: string
 37	  lastUpdated: number
 38	  limit?: number
 39	  remaining?: number
 40	  minTime?: number
 41	  /** El tope que un 429 declaró; se aplica cada vez que el limitador se crea. */
 42	  capRequests?: number
 43	  capWindowMs?: number
 44	}
 45	
 46	export interface RateLimitStatus {
 47	  enabled: boolean
 48	  active: boolean
 49	  queued: number
 50	  running: number
 51	}
 52	
 53	/** El error con que se rechaza lo que esperaba cuando el upstream responde 429. */
 54	export class RateLimitedByUpstreamError extends Error {
 55	  readonly code = 'RATE_LIMITED_BY_UPSTREAM'
 56	  constructor(readonly retryAfterMs: number) {
 57	    super(`upstream rate limited; retry after ${Math.ceil(retryAfterMs / 1000)}s`)
 58	    this.name = 'RateLimitedByUpstreamError'
 59	  }
 60	}
 61	
 62	/** Proveedores cuyo cupo es por modelo: un 429 de un modelo no frena a los demás. */
 63	const MODEL_SCOPED_PROVIDERS = new Set(['gemini', 'github'])
 64	/** La espera de un 429 que no dice cuánto esperar. */
 65	const DEFAULT_RETRY_AFTER_MS = 60_000
 66	/** El cupo que se repone cuando el cuerpo pide una espera. */
 67	const BODY_RETRY_REFRESH_AMOUNT = 60
 68	/** Por debajo de esta fracción del límite el limitador se ciñe al cupo restante; por encima de la otra, lo suelta. */
 69	const LOW_REMAINING = 0.1
 70	const HIGH_REMAINING = 0.5
 71	/** Margen restado al intervalo que sale del límite por minuto. */
 72	const MIN_TIME_MARGIN_MS = 10
 73	/** La separación que pide el aviso de exceso de Fireworks. */
 74	const OVER_LIMIT_MIN_TIME_MS = 200
 75	
 76	const positiveOrNull = (value: number | undefined) => (value && value > 0 ? value : null)
 77	
 78	export class RateLimitManager {
 79	  private readonly limiters = new Map<string, RequestLimiter>()
 80	  private readonly enabled = new Set<string>()
 81	  private readonly learned = new Map<string, LearnedLimit>()
 82	
 83	  constructor(private readonly queue: RateLimitQueueSettings = {}) {}
 84	
 85	  enable(credentialId: string): void {
 86	    this.enabled.add(credentialId)
 87	  }
 88	
 89	  /** Quita la protección y olvida los limitadores y lo aprendido de la credencial. */
 90	  disable(credentialId: string): void {
 91	    this.enabled.delete(credentialId)
 92	    for (const [key, limiter] of this.limiters) {
 93	      if (this.credentialOf(key) === credentialId) this.retire(key, limiter)
 94	    }
 95	    for (const [key, entry] of this.learned) {
 96	      if (entry.credentialId === credentialId) this.learned.delete(key)
 97	    }
 98	  }
 99	
100	  isEnabled(credentialId: string): boolean {
101	    return this.enabled.has(credentialId)
102	  }
103	
104	  /** Corre `task` dentro del limitador de la credencial, o directa si no está protegida. */
105	  withRateLimit<T>(provider: string, credentialId: string, model: string | null, task: () => Promise<T>, signal?: AbortSignal): Promise<T> {
106	    if (!this.isEnabled(credentialId)) return task()
107	    return this.limiterFor(provider, credentialId, model).schedule(task, signal)
108	  }
109	
110	  /** Aprende de las cabeceras de una respuesta; un 429 retira el limitador. */
111	  updateFromHeaders(provider: string, credentialId: string, headers: unknown, status: number, model: string | null = null): void {
112	    if (!this.isEnabled(credentialId) || !headers) return
113	    const plain = toPlainHeaders(headers)
114	    const names = provider === 'anthropic' || provider === 'claude' ? ANTHROPIC_HEADERS : STANDARD_HEADERS
115	    const read = (name: string) => plain[name.toLowerCase()] || null
116	    const key = this.keyOf(provider, credentialId, model)
117	
118	    if (status === 429) {
119	      // Retirar, no pausar: la ronda siguiente crea un limitador nuevo, que
120	      // vuelve a aplicar lo aprendido; lo que esperaba en éste iba a chocar
121	      // con el mismo 429.
122	      const limiter = this.limiters.get(key)
123	      if (limiter) this.retire(key, limiter, new RateLimitedByUpstreamError(parseResetTime(read(names.retryAfter)) || DEFAULT_RETRY_AFTER_MS))
124	      return
125	    }
126	
127	    const limiter = this.limiterFor(provider, credentialId, model)
128	    if (read(STANDARD_HEADERS.overLimit) === 'yes') {
129	      limiter.updateSettings({ minTime: OVER_LIMIT_MIN_TIME_MS })
130	      return
131	    }
132	
133	    const limit = Number.parseInt(read(names.limit) ?? '', 10)
134	    if (Number.isNaN(limit) || limit <= 0) return
135	    const remaining = Number.parseInt(read(names.remaining) ?? '', 10)
136	    const resetMs = parseResetTime(read(names.reset)) || DEFAULT_RETRY_AFTER_MS
137	    const updates: RequestLimiterSettings = { minTime: Math.max(0, Math.floor(60_000 / limit) - MIN_TIME_MARGIN_MS) }
138	    if (!Number.isNaN(remaining)) {
139	      if (remaining < limit * LOW_REMAINING) {
140	        Object.assign(updates, { reservoir: remaining, reservoirRefreshAmount: limit, reservoirRefreshInterval: resetMs })
141	      } else if (remaining > limit * HIGH_REMAINING) {
142	        Object.assign(updates, { minTime: this.minTimeFloor(), reservoir: null, reservoirRefreshAmount: null, reservoirRefreshInterval: null })
143	      }
144	    }
145	    limiter.updateSettings(updates)
146	    this.record(key, provider, credentialId, { limit, remaining, minTime: updates.minTime })
147	  }
148	
149	  /** Aprende de un cuerpo de error: la espera que pide y el tope que declara un 429. */
150	  updateFromResponseBody(provider: string, credentialId: string, body: unknown, status: number, model: string | null = null): void {
151	    if (!this.isEnabled(credentialId)) return
152	    const { retryAfterMs } = parseRetryAfterFromBody(body)
153	    if (retryAfterMs && retryAfterMs > 0) {
154	      this.limiterFor(provider, credentialId, model).updateSettings({
155	        reservoir: 0,
156	        reservoirRefreshAmount: BODY_RETRY_REFRESH_AMOUNT,
157	        reservoirRefreshInterval: retryAfterMs,
158	      })
159	    }
160	    if (status !== 429) return
161	    const cap = parseRequestCapFromBody(body)
162	    if (!cap) return
163	    const key = this.keyOf(provider, credentialId, model)
164	    const existing = this.limiters.get(key)
165	    if (existing) this.retire(key, existing)
166	    const settings = this.withFloor(requestCapSettings(cap))
167	    this.record(key, provider, credentialId, {
168	      limit: Math.max(1, Math.round((cap.requests * 60_000) / cap.windowMs)),
169	      minTime: settings.minTime,
170	      capRequests: cap.requests,
171	      capWindowMs: cap.windowMs,
172	    })
173	    // El 429 dice que la ventana ya se gastó: el cupo empieza vacío y se
174	    // repone `requests` al cerrarse.
175	    this.limiterFor(provider, credentialId, model).updateSettings({ reservoir: 0, ...settings })
176	  }
177	
178	  status(provider: string, credentialId: string, model: string | null = null): RateLimitStatus {
179	    const limiter = this.limiters.get(this.keyOf(provider, credentialId, model))
180	    const counts = limiter?.counts() ?? { QUEUED: 0, RUNNING: 0 }
181	    return { enabled: this.isEnabled(credentialId), active: Boolean(limiter), queued: counts.QUEUED, running: counts.RUNNING }
182	  }
183	
184	  allStatus(): Record<string, { queued: number; running: number }> {
185	    const all: Record<string, { queued: number; running: number }> = {}
186	    for (const [key, limiter] of this.limiters) {
187	      const counts = limiter.counts()
188	      all[key] = { queued: counts.QUEUED, running: counts.RUNNING }
189	    }
190	    return all
191	  }
192	
193	  learnedLimits(): Record<string, LearnedLimit> {
194	    return Object.fromEntries([...this.learned].map(([key, entry]) => [key, { ...entry }]))
195	  }
196	
197	  /** Los ajustes vigentes del limitador, o `null` si no hay ninguno. */
198	  settingsOf(provider: string, credentialId: string, model: string | null = null): Readonly<Required<RequestLimiterSettings>> | null {
199	    return this.limiters.get(this.keyOf(provider, credentialId, model))?.current() ?? null
200	  }
201	
202	  private keyOf(provider: string, credentialId: string, model: string | null): string {
203	    return MODEL_SCOPED_PROVIDERS.has(provider) && model ? `${provider}:${credentialId}:${model}` : `${provider}:${credentialId}`
204	  }
205	
206	  private credentialOf(key: string): string {
207	    return key.split(':')[1] ?? ''
208	  }
209	
210	  private minTimeFloor(): number {
211	    return Math.max(0, this.queue.minTimeBetweenRequestsMs ?? 0)
212	  }
213	
214	  private withFloor<S extends { minTime: number }>(settings: S): S {
215	    return { ...settings, minTime: Math.max(settings.minTime, this.minTimeFloor()) }
216	  }
217	
218	  /** El limitador de la clave, creado con los ajustes de cola y el tope aprendido si lo hay. */
219	  private limiterFor(provider: string, credentialId: string, model: string | null): RequestLimiter {
220	    const key = this.keyOf(provider, credentialId, model)
221	    let limiter = this.limiters.get(key)
222	    if (limiter) return limiter
223	    const rpm = positiveOrNull(this.queue.requestsPerMinute)
224	    const settings: RequestLimiterSettings = {
225	      maxConcurrent: positiveOrNull(this.queue.concurrentRequests),
226	      minTime: this.minTimeFloor(),
227	      reservoir: rpm,
228	      reservoirRefreshAmount: rpm,
229	      reservoirRefreshInterval: rpm ? 60_000 : null,
230	    }
231	    const learned = this.learned.get(key)
232	    if (learned?.capRequests && learned.capWindowMs) {
233	      const cap = this.withFloor(requestCapSettings({ requests: learned.capRequests, windowMs: learned.capWindowMs }))
234	      Object.assign(settings, { ...cap, reservoir: cap.reservoirRefreshAmount })
235	    }
236	    limiter = new RequestLimiter(settings)
237	    this.limiters.set(key, limiter)
238	    return limiter
239	  }
240	
241	  private retire(key: string, limiter: RequestLimiter, reason: unknown = new RateLimitedByUpstreamError(DEFAULT_RETRY_AFTER_MS)): void {
242	    this.limiters.delete(key)
243	    limiter.drop(reason)
244	    limiter.disconnect()
245	  }
246	
247	  private record(key: string, provider: string, credentialId: string, values: Partial<LearnedLimit>): void {
248	    const previous = this.learned.get(key)
249	    this.learned.set(key, { ...previous, ...values, provider, credentialId, lastUpdated: Date.now() })
250	  }
251	}

